#include "scamptrie_base.h"
#include "fib.hpp"
#include "image.hpp"
#include "image_build.hpp"
#include "image_io.hpp"

#include <iostream>
#include <memory>
#include <stdexcept>
#include <vector>
#include <sys/wait.h>
#include <cstdlib>

int main() {
    try {
        std::ios::sync_with_stdio(false);
        std::cin.tie(nullptr);
        size_t cases;
        if (!(std::cin >> cases)) throw std::runtime_error("wire exhausted");
        std::cout << "{\"results\":[";
        for (size_t c = 0; c < cases; ++c) {
            if (c) std::cout << ',';
            PrefixTable live;
            MemoryImage loaded;
            std::vector<nexthop_t> answers;
            std::vector<ImageData> saved;
            std::vector<bool> loads;
            size_t count;
            if (!(std::cin >> count)) throw std::runtime_error("wire exhausted");
            for (size_t i = 0; i < count; ++i) {
                char op;
                if (!(std::cin >> op)) throw std::runtime_error("wire exhausted");
                if (op == 'P') {
                    ip6_t ip = read_ip();
                    unsigned len;
                    uint64_t hop;
                    if (!(std::cin >> len >> hop)) throw std::runtime_error("wire exhausted");
                    if (len > 128) throw std::runtime_error("prefix length");
                    // Clear the host bits and store the normalized prefix.
                    uint64_t hi = ip.hi;
                    uint64_t lo = ip.lo;
                    if (len > 64) {
                        int bits = static_cast<int>(len) - 64;
                        uint64_t mask = bits >= 64 ? ~0ULL : (~0ULL << (64 - bits));
                        lo &= mask;
                    } else {
                        uint64_t mask = len == 0 ? 0 : (~0ULL << (64 - len));
                        hi &= mask;
                        lo = 0;
                    }
                    live.put(hi, lo, static_cast<uint8_t>(len), static_cast<uint32_t>(hop));
                } else if (op == 'Q' || op == 'I') {
                    size_t n;
                    if (!(std::cin >> n)) throw std::runtime_error("wire exhausted");
                    for (size_t j = 0; j < n; ++j) {
                        ip6_t ip = read_ip();
                        if (op == 'Q') {
                            uint32_t hop = 0;
                            answers.push_back(live.lookup(ip, hop) ? static_cast<nexthop_t>(hop)
                                                                     : LPM_INVALID_NH);
                        } else {
                            answers.push_back(loaded.lookup(ip));
                        }
                    }
                } else if (op == 'S') {
                    // A detached compact image of the complete live FIB.
                    saved.push_back(build_image(live));
                } else if (op == 'R') {
                    size_t id;
                    if (!(std::cin >> id)) throw std::runtime_error("wire exhausted");
                    if (id >= saved.size()) throw std::runtime_error("saved index");
                    loads.push_back(loaded.load(saved.at(id)));
                } else if (op == 'L') {
                    ImageData data = image_read_wire();
                    loads.push_back(loaded.load(data));
                } else {
                    throw std::runtime_error("wire opcode");
                }
            }
            std::cout << "{\"answers\":[";
            for (size_t i = 0; i < answers.size(); ++i) {
                if (i) std::cout << ',';
                if (answers[i] == LPM_INVALID_NH) std::cout << "null";
                else std::cout << answers[i];
            }
            std::cout << "],\"snapshots\":[";
            for (size_t i = 0; i < saved.size(); ++i) {
                if (i) std::cout << ',';
                image_write_json(saved[i]);
            }
            std::cout << "],\"loads\":[";
            for (size_t i = 0; i < loads.size(); ++i) {
                if (i) std::cout << ',';
                std::cout << (loads[i] ? "true" : "false");
            }
            std::cout << "]}";
        }
        std::cout << "]}\n";
        std::cout.flush();
        if (const char* feed = std::getenv("SCAMP_FEED_PID")) {
            int status;
            waitpid(std::strtol(feed, nullptr, 10), &status, 0);
        }
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
